<script setup lang="ts">import {computed} from 'vue';import type {Prediction} from '../types/domain';import {fixed} from '../utils/format';const props=defineProps<{rows:Prediction[]}>();defineEmits<{select:[id:string]}>();const calibrated=computed(()=>props.rows.some((p:any)=>p.original_prediction!==undefined));</script><template><div class="table-wrap"><table><thead><tr><th>待估点</th><th>x / y 米</th><th>预测含水率%</th><th v-if="calibrated">校正前% / 改变量 pp</th><th>空间方差 pp²</th><th>空间SD pp</th><th></th></tr></thead><tbody><tr v-for="p in rows" :key="p.query_id"><td>{{p.query_id}}</td><td>{{fixed(p.x,1)}} / {{fixed(p.y,1)}}</td><td>{{fixed(p.prediction)}}<small v-if="(p as any).calibration_locked"> 锁定</small></td><td v-if="calibrated">{{(p as any).original_prediction!==undefined?fixed((p as any).original_prediction)+' / '+fixed((p as any).calibration_change,3):'—'}}</td><td>{{fixed(p.variance,5)}}</td><td>{{fixed(p.standard_deviation)}}</td><td><button class="table-action" @click="$emit('select',p.query_id)">权重</button></td></tr></tbody></table></div></template>
